grant select on public.vps_instances to authenticated; grant all on public.vps_instances to service_role; alter table public.vps_instances enable row level security; drop policy if exists "Users can view their own vps instances" on public.vps_instances; create policy "Users can view their own vps instances" on public.vps_instances for select to authenticated using (exists (select 1 from public.services s where s.id = vps_instances.service_id and s.user_id = auth.uid()));